import {WORLD} from './world-data.js?v=0.7.0';
export {WORLD};
export const PATHS=['人间','修仙','修神','宇宙','多元'];
export function initWorld(s,country=0){if(!s.world)s.world={schema:1,country,planet:0,universe:0,path:0,rank:0,cycle:0,days:0,power:0,virtue:0,practice:0,strain:0,domain:null,visitedCountries:[country],visitedPlanets:[0],visitedUniverses:[0],pending:null,chronicle:[],completed:0,failures:0};return s.world;}
export function validateWorld(s){if(!s.world)return;const w=s.world,integer=x=>Number.isSafeInteger(x)&&x>=0;const fail=()=>{throw Error('诸天存档无效');};if(w.schema!==1||!integer(w.country)||!WORLD.countries[w.country]||!integer(w.planet)||!WORLD.planets[w.planet]||!integer(w.universe)||!WORLD.universes[w.universe]||!integer(w.path)||w.path>4||!integer(w.rank)||w.rank>=ranks(w.path).length)fail();for(const k of ['cycle','days','practice','completed','failures'])if(!integer(w[k])||w[k]>100000000)fail();for(const k of ['power','virtue','strain'])if(!Number.isFinite(w[k])||w[k]<0||w[k]>1e12)fail();if(w.strain>100||!(w.domain===null||(integer(w.domain)&&WORLD.domains[w.domain])))fail();for(const [key,max] of [['visitedCountries',100],['visitedPlanets',12],['visitedUniverses',9]])if(!Array.isArray(w[key])||w[key].length>max||new Set(w[key]).size!==w[key].length||w[key].some(i=>!integer(i)||i>=max))fail();if(!w.visitedCountries.includes(w.country)||!w.visitedPlanets.includes(w.planet)||!w.visitedUniverses.includes(w.universe)||!Array.isArray(w.chronicle)||w.chronicle.length>200||w.chronicle.some(x=>typeof x!=='string'||x.length>2000))fail();if(w.pending&&(!integer(w.pending.serial)||w.pending.serial!==w.cycle||!integer(w.pending.kind)||w.pending.kind>11))fail();if(w.path>=2&&w.domain===null)fail();if(w.path>0&&s.ended)fail();}
export function ranks(path){return [ ['凡尘历练'],WORLD.immortals,WORLD.gods,WORLD.cosmic,WORLD.multiverse][path]||[];}
export const title=s=>{const w=initWorld(s);return ranks(w.path)[w.rank];};
function note(s,text){const w=initWorld(s);w.chronicle.unshift(`${PATHS[w.path]} · ${w.days}日｜${text}`);w.chronicle=w.chronicle.slice(0,200);}
export function entryReasons(s){return [s.ended?'此生已经结束，无法复活':'',s.pending||s.transition||s.familyChoice?'请先完成当前人生选择':'',Math.floor(s.day/365)<60&&s.progress<1?'年满60岁或抵达国家主席':'',s.stats.some(x=>x<=100)?'五维均超过100':'',s.xian<1?'至少保有1点仙值':''].filter(Boolean);}
export function enterImmortal(s){const w=initWorld(s);if(w.path!==0||entryReasons(s).length)return false;s.xian--;w.path=1;w.rank=0;w.power=0;w.practice=0;w.virtue=0;w.days=0;w.pending=null;note(s,'辞别凡尘，启灵入道。凡间年龄、任职与家族停留于此日，另记道历；原寿命兑换仍适用于凡间。');return true;}
export function canTravel(s,kind,id){const w=initWorld(s);if(!Number.isInteger(id)||s.ended||w.pending||s.pending||s.transition||s.familyChoice)return false;if(kind==='country')return !!WORLD.countries[id]&&w.path===0&&Math.floor(s.day/365)>=18&&s.stage==='work'&&w.country!==id&&w.cycle<Math.floor(s.day/365);if(kind==='planet')return !!WORLD.planets[id]&&w.path>=2&&w.power>=20&&w.planet!==id;if(kind==='universe')return !!WORLD.universes[id]&&w.path===4&&w.power>=20&&w.universe!==id;return false;}
export function travel(s,kind,id){if(!Number.isInteger(id)||!canTravel(s,kind,id))return false;const w=initWorld(s);const [field,list,items]=kind==='country'?['country','visitedCountries',WORLD.countries]:kind==='planet'?['planet','visitedPlanets',WORLD.planets]:['universe','visitedUniverses',WORLD.universes];w[field]=id;if(!w[list].includes(id))w[list].push(id);note(s,`抵达${items[id].name}${kind==='country'?'，开始外交驻访，凡间任职档案保留原籍':''}。`);if(kind!=='country'){w.power-=20;w.strain=Math.min(100,w.strain+5);}return true;}
export function chooseDomain(s,id){const w=initWorld(s);if(w.path!==1||w.rank!==9||w.pending||!WORLD.domains[id]||!Number.isInteger(id))return false;w.domain=id;return true;}
export function requirements(s){const w=initWorld(s),r=w.rank+1;return {power:Math.round((w.path===1?100:w.path===2?320:w.path===3?800:1800)*r*r),virtue:r*(w.path===1?2:w.path===2?3:5),practice:r*2,balance:.25,strain:60};}
export function breakthroughReasons(s){const w=initWorld(s),g=requirements(s),reasons=[];if(w.path===0)return ['先开启修仙'];if(w.pending)reasons.push('先完成历练抉择');if(w.power<g.power)reasons.push(`修为 ${Math.floor(w.power)} / ${g.power}`);if(w.virtue<g.virtue)reasons.push(`功德 ${w.virtue} / ${g.virtue}`);if(w.practice<g.practice)reasons.push(`实践 ${w.practice} / ${g.practice}`);if(Math.min(...s.stats)/Math.max(...s.stats)<g.balance)reasons.push('五维最低值须达到最高值的25%');if(w.strain>g.strain)reasons.push('心劫须降至60以内');if(w.path===1&&w.rank===9&&w.domain===null)reasons.push('选择一个神职');if(w.path===2&&w.rank===8&&w.visitedPlanets.length<3)reasons.push('至少踏访3颗星球');if(w.path===3&&w.rank===3&&w.visitedPlanets.length<6)reasons.push('至少踏访6颗星球');if(w.path===4&&w.rank===3&&w.visitedUniverses.length<5)reasons.push('至少联结5个宇宙');return reasons;}
export function breakthrough(s){const w=initWorld(s);if(s.ended||w.path===0||breakthroughReasons(s).length)return false;const before=title(s);if(w.path===4&&w.rank===3){if(w.completed)return false;w.completed=1;note(s,'诸界共议达成：多元秩序建立。仍可继续巡游与治理。');return true;}if(w.rank===ranks(w.path).length-1){w.path++;w.rank=0;}else w.rank++;w.power=0;w.practice=0;w.virtue=0;w.strain=Math.max(0,w.strain-15);note(s,`${before} → ${title(s)}。${w.path===4&&w.rank===0?'宇宙之主之后，界外星门正式开启。':''}`);return true;}
// Twelve authored dilemmas; the context/resource condition determines the best response.
const DILEMMAS=[
 ['粮脉告急','储备不足而灾情正在蔓延','跨域调粮并公开配给','先保仓储，组织疏散和协作','封锁消息维持账面繁荣','筹粮与救助必须同时核实承载量。'],
 ['古卷异文','新旧典籍对同一法则记载相反','组织异本校勘并试验','保留异本，先在小范围验证','销毁不合主流的版本','尊重证据与不同文明的记忆。'],
 ['山川失衡','山脉工程提升产出却损伤水源','修复水土并补偿居民','暂停扩建，邀请相邻领域协作','继续扩建，把损失转嫁下游','劳的实践须同时接受德与智的约束。'],
 ['界门来客','异域移民请求穿过承载有限的通道','分批安置并共享教育医疗','先开救援走廊，协商分流','按出身永久拒绝救助','有限资源下仍须保有公平与救援。'],
 ['雷律之争','两地对誓约和惩罚的理解冲突','共同立约，公开复核与申诉','先暂停惩戒，启动跨域听证','用更强雷霆强迫服从','神权的边界由职责与问责共同确定。'],
 ['灵疫初起','传播机制未知，传言比病情更快','公开证据并组织医护协作','先隔离风险源，调援并保障生计','隐瞒病情，出售未经验证的神药','体是基础，求证与救护不能割裂。'],
 ['匠院争鸣','高效器械挤压旧工匠生计','开放技术并投入再培训','先试点并保障过渡期收入','垄断技术，驱逐旧工匠','智的进步需要劳的转化与德的引导。'],
 ['万象失色','繁荣之地的居民失去创作与表达','支持多元艺术及公共空间','先保护创作自由，开放共享场地','只保留歌颂权力的作品','美丰富精神，也是完整成长的一部分。'],
 ['星路漂移','观测偏差可能令航队迷航','共享观测并修订导航','暂停高风险航班，联合复测','删掉异常读数继续远航','科普仅为灵感，游戏星路规则属于架空设定。'],
 ['时间歧路','两界一年流速不同，债务期限引发争执','建立双时标与公平换算','冻结争议债务并共同核验','按本界时间强征全部债务','多宇宙治理须先理解规则差异。'],
 ['记忆之河','两族保存了互相冲突的祖先叙事','并列保存证词，共建档案','先保护遗存，再邀请双方协商','只允许胜者保存记忆','存真求同，不以权力替代证据。'],
 ['权柄试炼','短期收益诱使治理者耗尽未来资源','设定上限并修复生态','降低开采，公开代价并求援','透支一切换取个人升阶','所有权能都对应持续的公共责任。']
];
export function worldEvent(s){const w=initWorld(s);if(!w.pending)return null;const d=DILEMMAS[w.pending.kind],n=w.pending.serial,u=WORLD.universes[w.universe],p=WORLD.planets[w.planet],c=WORLD.countries[w.country],domain=WORLD.domains[w.domain];const rich=(n+w.country+w.planet+w.universe)%2===0,offset=(Math.imul(n+1,2654435761)>>>0)%3,good=rich?d[2]:d[3],other=rich?d[3]+'，但错失可直接救助的时机':d[2]+'，超出当前资源承载';const options=[good,other,d[4]].map((_,i)=>[good,other,d[4]][(i+offset)%3]);return {title:d[0],text:`${w.path===0?c.name+' · '+c.polity:w.path===1?p.name+' · '+title(s):w.path===2?(domain?.name||'未定')+'神 · '+p.name:u.name+' · '+p.name}：${d[1]}。${rich?'当前资源充足，可以立即开展系统治理。':'当前资源紧张，必须先控制风险并寻求协作。'}${w.path===0?'本地难题：'+c.crisis+'；任用约束：'+c.hiring+'。':'星球法则：'+p.law+'；本地危机：'+p.hazard+'。'+(domain?'你的职掌：'+domain.duty+'，须防范'+domain.crisis+'。':'')+(w.path>=3?'此界规则：'+u.rule+'。':'')}`,options,answer:(3-offset)%3,explanation:d[5],source:w.path===0?'素材库 · 百国政体与地理草案':w.pending.kind===1||w.pending.kind===10?'素材库 · 古籍校勘与文明档案灵感':'素材库 · 神职、法则与多元宇宙原创草案'};}
export function train(s,days=30,activity=0){const w=initWorld(s);if(s.ended||w.path===0||w.pending||![1,7,30,365].includes(days)||!Number.isInteger(activity)||activity<0||activity>4)return 0;const actual=Math.min(days,365-w.days%365),quality=days===1?1:days===7?.85:days===30?.68:.5;w.days+=actual;const affinity=w.path>=2?WORLD.domains[w.domain].affinity:WORLD.planets[w.planet].focus;const balance=Math.min(...s.stats)/Math.max(...s.stats);w.power+=actual*(.6+balance)*quality*(activity===affinity?1.2:1);for(let i=0;i<5;i++)s.stats[i]+=actual*(i===activity?.09:.025);w.strain=Math.max(0,w.strain-actual*(activity===2?.3:.04));if(w.days%365===0){w.cycle++;w.pending={serial:w.cycle,kind:(w.cycle+s.seed+w.planet+w.universe)%12};}return actual;}
export function mission(s){const w=initWorld(s);if(w.path!==0||s.ended||s.pending||s.transition||s.familyChoice||w.pending||s.stage!=='work'||Math.floor(s.day/365)<18||w.cycle>=Math.floor(s.day/365))return false;w.cycle=Math.floor(s.day/365);w.pending={serial:w.cycle,kind:(w.cycle+w.country+s.seed)%12};return true;}
export function resolveWorld(s,index){const w=initWorld(s),e=worldEvent(s);if(!e||![0,1,2].includes(index)||s.ended)return null;const ok=index===e.answer;w.pending=null;w.practice++;if(ok){w.virtue+=3;w.power+=80;w.strain=Math.max(0,w.strain-8);}else{w.failures++;w.power=Math.max(0,w.power-30);w.strain=Math.min(100,w.strain+18);}note(s,`${e.title}：${e.options[index]}。${ok?'功德与实践增长':'留下心劫，可继续修复'}。${e.explanation}`);return {...e,ok,choice:e.options[index]};}
